/**
 * @name Dangerous string formatting with user input
 * @description String formatting operations with user-controlled input could lead to injection attacks
 * @kind problem
 * @problem.severity medium
 * @id py/string-format-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module StringFormatConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("format").getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("str").getMember("format").getACall() and
      sink = call.getArg(0)
    )
  }
}

module StringFormatFlow = TaintTracking::Global<StringFormatConfig>;

from DataFlow::Node source, DataFlow::Node sink
where StringFormatFlow::flow(source, sink)
select sink, "User-controlled input reaches string formatting operation, which could lead to injection attacks."

/**
 * @name Integer overflow or unsafe numeric conversions
 * @description Integer conversions that could lead to overflow or other numeric issues
 * @kind problem
 * @problem.severity medium
 * @id py/unsafe-numeric-conversion
 * @tags security
 *        external/cwe/cwe-190
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module NumericConversionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("int").getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("float").getACall() and
      sink = call.getArg(0)
    )
  }
}

module NumericConversionFlow = TaintTracking::Global<NumericConversionConfig>;

from DataFlow::Node source, DataFlow::Node sink
where NumericConversionFlow::flow(source, sink)
select sink, "User-controlled input reaches numeric conversion operation, which could lead to integer overflow or other numeric issues."

/**
 * @name User-controlled input reaching type conversion operations
 * @description Check if user-controlled input reaches type conversion operations that could cause security issues
 * @kind path-problem
 * @problem.severity medium
 * @id py/type-conversion-taint
 * @tags security
 *        external/cwe/cwe-704
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module TypeConversionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin(["int", "float", "bool", "str"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module TypeConversionFlow = TaintTracking::Global<TypeConversionConfig>;
import TypeConversionFlow::PathGraph

from TypeConversionFlow::PathNode source, TypeConversionFlow::PathNode sink
where TypeConversionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled input reaches type conversion operation $@.", source.getNode(), "user input"
